pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor address and unlock time candidate and deposit amount
    function testFuzz_property(address actor, uint256 unlockTime, uint256 amount) public {
        // keep amount in a reasonable range and non-zero to pass MinSum check if needed
        amount = bound(amount, 1 wei, 10 ether);
        // ensure actor is not zero address (EOA ok)
        vm.assume(actor != address(0));

        // Fund the actor and perform Put as that actor
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // The general property: reference sets unlockTime = max(unlockTime, block.timestamp)
        // We observe c only via its public mapping getter Acc(address) which returns (unlockTime,balance)
        (uint accUnlockTime, uint accBalance) = c.Acc(actor);

        // The reference always sets acc.balance increased by amount; both versions do that, so check balance
        // (not strictly necessary for distinguishing unlockTime, but keeps admissible inputs sane)
        assertTrue(accBalance >= amount);

        // Now assert the universal property that holds on reference: accUnlockTime >= block.timestamp
        // and if provided unlockTime > block.timestamp then accUnlockTime == unlockTime.
        // We implement a single assertion that must hold for the reference for ALL inputs and that the mutant
        // will violate for some inputs (when unlockTime > block.timestamp).

        // Single required assertion reading c: assertTrue(condition)
        if (unlockTime > block.timestamp) {
            // In the correct contract accUnlockTime should equal the provided future unlockTime
            assertTrue(accUnlockTime == unlockTime);
        } else {
            // If provided unlockTime is in the past or now, correct contract sets to block.timestamp
            assertTrue(accUnlockTime == block.timestamp);
        }
    }
}

