        // ensure we use a desiredUnlock that can be > block.timestamp to expose the mutant
        // but still keep domain wide
        uint256 _desired = bound(desiredUnlock, block.timestamp, type(uint256).max);

        // give the actor some ETH to send
        uint256 sendAmt = 1 ether;
        vm.deal(actor, sendAmt);

        // actor calls Put with desired unlock time and some value
        vm.prank(actor);
        bool ok;
        try c.Put{value: sendAmt}(_desired) {
