    function testFuzz_property(address actor, uint256 unlockTime) public {
        // keep actor as a non-zero address and not the test contract to be realistic
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Bound unlockTime to a reasonable future window so that some inputs are > block.timestamp
        // but keep domain wide: allow values from (block.timestamp - 1000) .. (block.timestamp + 1 days)
        uint256 ut = bound(unlockTime, block.timestamp > 1000 ? block.timestamp - 1000 : 0, block.timestamp + 1 days);

        // ensure actor has some ETH to send
        vm.deal(actor, 1 ether);

        // perform the call as actor sending some value (use 1 wei to avoid MinSum requirement in Collect)
        vm.prank(actor);
        c.Put{value: 1 wei}(ut);

        // The reference guarantees that Acc[actor].unlockTime >= block.timestamp and if ut > block.timestamp
        // then Acc[actor].unlockTime == ut. The mutant that always sets block.timestamp will break when ut > block.timestamp.
        uint acctUnlock = c.Acc(actor).unlockTime;

        // Single assertion: after Put, unlockTime is >= block.timestamp (this holds for reference for all admissible inputs)
        // and specifically if the provided ut is strictly greater than block.timestamp then it must equal ut.
        // We encode this as a single boolean expression to assertTrue exactly once.
        bool ok = (acctUnlock >= block.timestamp) && (ut <= block.timestamp || acctUnlock == ut);
        assertTrue(ok);
    }
}

