        uint256 sendVal = 1 ether;
        vm.deal(actor, sendVal);

        // record timestamp before call
        uint256 before = block.timestamp;

        // make the call as the actor, sending 1 ether
        vm.prank(actor);
        c.Put{value: sendVal}(unlockTime);

        // Immediately read the stored unlockTime for actor
