        // The original contract C declares Acc as public mapping (mapping(address => Holder) public Acc;)
        // Solidity generates a getter with signature: function Acc(address) public view returns (uint unlockTime, uint balance);
        // Call it as external (through the c instance) to obtain the values.
        try c.Acc(adr) returns (uint256 ut, uint256 bal) {
            return (ut, bal);
        } catch {
            return (0, 0);
        }
    }
