import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: actor (caller) and _unlockTime. We let the fuzzer choose an address
    // and an arbitrary timestamp. We must ensure actor is not the zero address.
    function testFuzz_property(address actor, uint256 _unlockTime) public {
        vm.assume(actor != address(0));

        // Give the actor some ETH to call Put with a small nonzero amount.
        uint256 sendVal = 1 ether;
        vm.deal(actor, sendVal);

        // actor calls Put with the fuzzed _unlockTime
        vm.prank(actor);
        bool ok;
        try c.Put{value: sendVal}(_unlockTime) {
            ok = true;
        } catch {
            // If Put reverts, treat as failure to complete; for the reference contract Put should not revert here.
            ok = false;
        }

        // The universal property: for EVERY admissible input (any nonzero actor and any _unlockTime),
        // the reference contract completes the call (ok == true) and stores Acc[actor].unlockTime >= block.timestamp.
        // We assert the primary invariant using the public getter Acc(actor).unlockTime.
        // Read the stored unlockTime via the public mapping getter Acc(address).
        (uint256 storedUnlockTime, ) = getAcc(actor);

        // The single assertion: when Put returned successfully, the stored unlockTime is >= current block.timestamp.
        // The reference contract satisfies this for all inputs; the mutant that assigns acc.unlockTime = _unlockTime
        // can produce storedUnlockTime < block.timestamp for some fuzzed _unlockTime, causing this assert to fail.
        assertTrue(ok && storedUnlockTime >= block.timestamp);
    }

    // helper to read the public struct mapping Acc via the auto-generated getter
    // The contract C defines: mapping(address => Holder) public Acc; with Holder { uint unlockTime; uint balance; }
    function getAcc(address a) internal returns (uint256 unlockTime, uint256 balance) {
        // the public getter has signature: function Acc(address) external view returns (uint256 unlockTime, uint256 balance);
        (bool s, bytes memory b) = address(c).call(abi.encodeWithSignature("Acc(address)", a));
        if (!s) return (0,0);
        (unlockTime, balance) = abi.decode(b, (uint256, uint256));
    }
}

